import {FACILITIES,facilityWasteProduction} from './facilities.js?v=architecture-collection-41';
export function facilityWasteSources(c){return (c.stats.facilityPlots||[]).map(p=>({root:p.root,type:p.type,name:FACILITIES[p.type].name,x:p.x,y:p.y,tiles:p.ids.length,operating:p.operating,rate:p.ids.reduce((s,i)=>s+facilityWasteProduction(c.tiles[i]),0),waiting:p.ids.reduce((s,i)=>s+(c.tiles[i].waste||0),0)}));}
export function facilityGarbageInspection(c,t){if(!FACILITIES[t.type])return '';const s=facilityWasteSources(c).find(p=>p.root===t.facilityRoot);return s?`<p>Facility garbage: ${s.rate.toFixed(2)} units/month · ${s.waiting.toFixed(2)} waiting across ${s.tiles} tiles. Collection uses roads beside the whole facility. Connect those roads to disposal capacity or a garbage-export route. New production stops while the facility is inactive; existing waste remains.</p>`:'<p>This incomplete facility produces no new garbage. Existing waste still needs collection.</p>';}
export function facilityWasteReport(c){const sources=facilityWasteSources(c);if(!sources.length)return '';const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});return `<details><summary>Airports and seaports · garbage</summary><p>Operating facilities generate ${fmt(sources.reduce((s,p)=>s+p.rate,0))} units/month, included in city garbage production. Airport tiles produce 0.48 each; seaport tiles produce 0.32 each. Undeveloped or inactive facilities produce none.</p><div class="table-scroll"><table aria-label="Port facility garbage"><thead><tr><th>Facility</th><th>Status / tiles</th><th>Units/month</th><th>Waiting</th></tr></thead><tbody>${sources.map(p=>`<tr><th scope="row">${p.name} · ${p.x+1}, ${p.y+1}</th><td>${p.operating?'Operating':'Inactive'} · ${p.tiles}</td><td>${fmt(p.rate)}</td><td>${fmt(p.waiting)}</td></tr>`).join('')}</tbody></table></div><p>Inspect any tile to review the whole facility’s backlog. Roads beside any part of its footprint can collect garbage. Navigable water access alone does not provide garbage collection.</p></details>`;}
